-- World Essentials reviewed overlay; upstream certificate: tools/community-kbw-sources.json
if not getActivatedMods():contains("KnoxCommunityTilepack") then return end
-- AUTO-GENERATED by pz_craft_loops/kbw_tilepatch.py -- do not edit by hand.
-- Gives Community Tilepack TVs vanilla's screen overlay sprites (the pack has no screen art).
-- Screen choice (test card / broadcast or tape / off) stays with vanilla IsoTelevision logic.
local SCREENS = {
    ["DylansRandomFurniture02_36"] = { "KBWCommunityTVScreens_0", "KBWCommunityTVScreens_1", "KBWCommunityTVScreens_2" },
    ["DylansRandomFurniture02_37"] = { "KBWCommunityTVScreens_3", "KBWCommunityTVScreens_4", "KBWCommunityTVScreens_5" },
    ["DylansRandomFurniture02_38"] = { "KBWCommunityTVScreens_6", "KBWCommunityTVScreens_7", "KBWCommunityTVScreens_8" },
    ["DylansRandomFurniture02_39"] = { "KBWCommunityTVScreens_9", "KBWCommunityTVScreens_10", "KBWCommunityTVScreens_11" },
    ["KBWCommunityIceShell_176"] = { "KBWCommunityTVScreens_12", "KBWCommunityTVScreens_13", "KBWCommunityTVScreens_14" },
    ["KBWCommunityIceShell_177"] = { "KBWCommunityTVScreens_15", "KBWCommunityTVScreens_16", "KBWCommunityTVScreens_17" },
    ["KBWCommunityIceShell_178"] = { "KBWCommunityTVScreens_18", "KBWCommunityTVScreens_19", "KBWCommunityTVScreens_20" },
    ["KBWCommunityIceShell_179"] = { "KBWCommunityTVScreens_21", "KBWCommunityTVScreens_22", "KBWCommunityTVScreens_23" },
    ["KBWCommunityIceShell_180"] = { "KBWCommunityTVScreens_24", "KBWCommunityTVScreens_25", "KBWCommunityTVScreens_26" },
    ["KBWCommunityIceShell_181"] = { "KBWCommunityTVScreens_27", "KBWCommunityTVScreens_28", "KBWCommunityTVScreens_29" },
    ["KBWCommunityIceShell_205"] = { "KBWCommunityIceShell_221", "KBWCommunityIceShell_237", "KBWCommunityIceShell_253" },
    ["KBWCommunityIceShell_206"] = { "KBWCommunityIceShell_222", "KBWCommunityIceShell_238", "KBWCommunityIceShell_254" },
}

-- Explicit bounded cache: Kahlua weak tables do not provide reliable eviction.
-- New isolated sprites share behavior while old placed objects retain legacy support.
local privateSprites = require "WorldEssentialsCommunitySprites"
local privateEntries = {}
for name, entry in pairs(SCREENS) do
    local privateName = privateSprites[name]
    if privateName then
        privateEntries[privateName] = entry
    end
end
for name, entry in pairs(privateEntries) do SCREENS[name] = entry end

local Health = require "WorldEssentialsPatchHealth"
Health.set("Community TV repair","PENDING","Awaiting Knox finalize hook; bounded cache=512, client fallback=125 squares/player/game-minute")
local seen, ring, head = {}, {}, 0
local failures = 0
local function applyScreens(obj, source)
    if not obj or not instanceof(obj, "IsoTelevision") then return end
    local spr, sq = obj:getSprite(), obj:getSquare()
    local name = spr and spr:getName()
    local list = name and SCREENS[name]
    if not list or not sq then return end
    local old = seen[obj]
    if old and old.name == name and old.square == sq and not obj:isMovedThumpable() then return end
    local ok = pcall(function()
        -- Validate all resources before clearing an existing screen list.
        if not isServer() then
            local a,b,c = getSprite(list[1]),getSprite(list[2]),getSprite(list[3])
            if not a or not b or not c then error("screen sprite unavailable") end
            obj:clearTvScreenSprites()
            obj:addTvScreenSprite(a); obj:addTvScreenSprite(b); obj:addTvScreenSprite(c)
        end
        if obj:isMovedThumpable() then
            obj:setMovedThumpable(false)
            sq:RecalcAllWithNeighbours(true)
        end
    end)
    if not ok then
        failures = failures + 1
        Health.counter("Community TV repair","failures",1)
        if failures == 1 then print("[WorldEssentials][Community] TV repair failed; later events will retry") end
        return
    end
    Health.counter("Community TV repair","repaired",1)
    head = head % 512 + 1
    local expired = ring[head]
    if expired then seen[expired] = nil end
    ring[head] = obj
    seen[obj] = {name=name,square=sq}
end

local function scanSquare(sq, source)
    if not sq then return end
    local objs = sq:getObjects()
    for i = 0, objs:size() - 1 do
        applyScreens(objs:get(i), source)
    end
end

-- Shared certified dispatcher retains the TV cache and client/server behaviour.
require("WorldEssentialsCommunityGrid").register("tv", SCREENS, applyScreens)
-- Newly built TVs (B42 event; argument shape guarded).
if Events.OnTileObjectAdded then
    Events.OnTileObjectAdded.Add(function(a, b)
        if a and instanceof(a, "IsoObject") then applyScreens(a, "OnTileObjectAdded")
        elseif a and instanceof(a, "IsoGridSquare") then scanSquare(a, "OnTileObjectAdded") end
        if b and instanceof(b, "IsoObject") then applyScreens(b, "OnTileObjectAdded") end
    end)
end
if Events.OnObjectAdded then
    Events.OnObjectAdded.Add(function(obj) applyScreens(obj, "OnObjectAdded") end)
end

-- Newly BUILT TVs: none of the events above fire for KBW builds (confirmed in console: only
-- LoadGridsquare ever logged). KBW builds TVs through NativeObjectFactory.create (which calls
-- setMovedThumpable(true)) and then calls NativeObjectFactory.finalize via the module table, so
-- wrapping finalize at runtime catches every new TV right after it enters the square. We do not
-- edit KBW's files; this only wraps the function in memory.
local function hookKBWFinalize(source)
    local okR, NOF = pcall(require, "KnoxBuildworks/BuildingObjects/NativeObjectFactory")
    if not okR or type(NOF) ~= "table" or type(NOF.finalize) ~= "function" then return end
    if NOF.__kbwCommunityTVHooked then return end
    local orig = NOF.finalize
    local function pack(...) return {n=select("#",...),...} end
    NOF.finalize = function(object, state, square, ...)
        local result = pack(orig(object, state, square, ...))
        if state and state.type == "television" then
            seen[object] = nil
            applyScreens(object, "KBWFinalize")
        end
        return unpack(result,1,result.n)
    end
    NOF.__kbwCommunityTVHooked = true
    Health.set("Community TV repair","OK","Load/object/finalize hooks; bounded cache=512; client-only fallback=125 squares/player/game-minute")
end
if Events.OnGameStart then Events.OnGameStart.Add(function() hookKBWFinalize("OnGameStart") end) end
if Events.OnServerStarted then Events.OnServerStarted.Add(function() hookKBWFinalize("OnServerStarted") end) end

-- Multiplayer clients never run the server-side finalize, and a TV another player builds arrives
-- without a LoadGridsquare. A light scan around each local player every in-game minute covers
-- that case. TV cache retention is explicitly bounded.
-- Client-only remote construction fallback. At most 125 square lookups per
-- local player per game minute; 15 slices cover the original 25x25x3 region.
-- No OnTick, network request, or retained square/object scan queue.
local scanOffset = 0
local function scanNearPlayers()
    if isServer() then return end
    local cell = getCell()
    if not cell then return end
    for p = 0, getNumActivePlayers()-1 do
        local pl = getSpecificPlayer(p)
        if pl then
            local px,py,pz = math.floor(pl:getX()),math.floor(pl:getY()),math.floor(pl:getZ())
            for i=0,124 do
                local n=(scanOffset+i)%1875
                local x=px+math.floor(n/25)%25-12
                local y=py+n%25-12
                local z=pz+math.floor(n/625)-1
                scanSquare(cell:getGridSquare(x,y,z),"remote-fallback")
            end
        end
    end
    scanOffset=(scanOffset+125)%1875
end
if not isServer() and Events.EveryOneMinute then Events.EveryOneMinute.Add(scanNearPlayers) end
